def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_of_signed_digits(num):
        num_str = str(num)
        if num < 0:
            signed_digits = [int(num_str[0] + num_str[1])] + [int(d) for d in num_str[2:]]
        else:
            signed_digits = [int(d) for d in num_str]
        return sum(signed_digits)

    return sum(1 for num in arr if sum_of_signed_digits(num) > 0)
